/* Frozen font and Word template for v2.8, and for v2.9 in file:// mode. */
if (location.protocol === "file:" || document.body.dataset.version === "2.8") {
  const bytes = value => Uint8Array.from(atob(value), char => char.charCodeAt(0));
  getCyrFont = async () => bytes("");
  embeddedTemplate = async () => bytes("").buffer;
}
